public static class ArrangementPointerAcceptance {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;
 public static object Main(){if(!Application.isPlaying)throw new Exception("Play required");Application.runInBackground=true;EditorApplication.isPaused=false;int checks=0,frames=0,last=-1;double deadline=EditorApplication.timeSinceStartup+30;void Check(bool v,string why){checks++;if(!v)throw new Exception(why);}var owned=new List<GameObject>();GameObject Make(string n){var g=new GameObject(n);owned.Add(g);return g;}var go=Make("Owned drag pointer runtime");go.SetActive(false);var r=go.AddComponent<EchoSphereRuntime>();r.enabled=false;go.SetActive(true);var rt=r.GetType();void Set(string n,object v)=>rt.GetField(n,F).SetValue(r,v);object Get(string n)=>rt.GetField(n,F).GetValue(r);object Call(string n,params object[] args)=>rt.GetMethod(n,F).Invoke(r,args);
 var player=Make("Owned drag core");var core=player.AddComponent<PlayerCoreController2D>();var camera=Make("Owned drag camera").AddComponent<Camera>();camera.enabled=false;camera.transform.position=new Vector3(0,0,-10);Set("_camera",camera);Set("_player",player.transform);Set("_playerCore",core);Set("_mainMenu",false);Set("_tutorialStep",-1);Set("_shopSaveLoaded",true);Set("_shopSave",Activator.CreateInstance(rt.GetNestedType("ShopSaveData",F)));var sphere=Make("Owned draggable sphere").AddComponent<SphereAttackAgent>();sphere.transform.position=Vector2.right*70*SpherePlacementRules.SourcePixelsToWorld;sphere.Initialize(r,player.transform,SphereId.Standard,12);((List<SphereAttackAgent>)Get("_spheres")).Add(sphere);
 var host=Make("Owned drag UIDocument");var panel=ScriptableObject.CreateInstance<PanelSettings>();panel.themeStyleSheet=Resources.Load<ThemeStyleSheet>("EchoSphere/SourceUiTheme");panel.scale=1;panel.sortingOrder=200000;var doc=host.AddComponent<UIDocument>();doc.panelSettings=panel;doc.sortingOrder=200000;var root=doc.rootVisualElement;root.style.position=Position.Absolute;root.style.left=root.style.top=root.style.right=root.style.bottom=0;root.pickingMode=PickingMode.Position;Set("_nativeRunField",root);Set("_nativeMobileGestureRoot",root);
 root.RegisterCallback((EventCallback<PointerDownEvent>)Delegate.CreateDelegate(typeof(EventCallback<PointerDownEvent>),r,rt.GetMethod("NativeMobileDown",F)));root.RegisterCallback((EventCallback<PointerMoveEvent>)Delegate.CreateDelegate(typeof(EventCallback<PointerMoveEvent>),r,rt.GetMethod("NativeMobileMove",F)));root.RegisterCallback((EventCallback<PointerUpEvent>)Delegate.CreateDelegate(typeof(EventCallback<PointerUpEvent>),r,rt.GetMethod("NativeMobileUp",F)));root.RegisterCallback((EventCallback<PointerCancelEvent>)Delegate.CreateDelegate(typeof(EventCallback<PointerCancelEvent>),r,rt.GetMethod("NativeMobileCancel",F)));
 void Send(string kind,Vector2 point){var raw=new Event{type=kind=="down"?EventType.MouseDown:kind=="move"?EventType.MouseMove:EventType.MouseUp,button=0,mousePosition=point};if(kind=="down"){using(var e=PointerDownEvent.GetPooled(raw)){e.target=root;root.SendEvent(e);}}else if(kind=="move"){using(var e=PointerMoveEvent.GetPooled(raw)){e.target=root;root.SendEvent(e);}}else if(kind=="cancel"){using(var e=PointerCancelEvent.GetPooled(raw)){e.target=root;root.SendEvent(e);}}else{using(var e=PointerUpEvent.GetPooled(raw)){e.target=root;root.SendEvent(e);}}}
 EditorApplication.CallbackFunction tick=null;void Finish(string status){EditorApplication.update-=tick;Call("CancelSphereArrangement");foreach(var g in owned.Where(g=>g!=null&&g!=go).ToArray())UnityEngine.Object.DestroyImmediate(g);UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(panel);Directory.CreateDirectory("Library/arrangement-acceptance");File.WriteAllText("Library/arrangement-acceptance/pointer.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status,checks,scope="actual attached UIDocument routed pointer move, preview, commit, cancel; isolated runtime; not physical Android"}));}
 tick=()=>{try{if(!Application.isPlaying||EditorApplication.timeSinceStartup>deadline){Finish("FAIL deadline");return;}if(last==Time.frameCount)return;last=Time.frameCount;if(++frames<5)return;Check(root.panel!=null&&root.worldBound.width>300,"attached layout");Vector2 center=root.worldBound.center;Vector2 start=center+Vector2.right*70,finish=center+new Vector2(110,25);Send("down",start);Check(!r.IsSphereArrangementPaused,"down does not pause");Send("move",finish);Check(r.IsSphereArrangementPaused,"actual moved callback pauses");var ghost=Get("_nativeMobileGhost");Check(ghost!=null,"preview built during freeze");Check((bool)ghost.GetType().GetField("Valid",F).GetValue(ghost),"preview uses valid production placement");Send("up",finish);Check(!r.IsSphereArrangementPaused,"actual up resumes");Check(Vector2.Distance(sphere.transform.position,new Vector2(110,-25)*SpherePlacementRules.SourcePixelsToWorld)<.001,"actual commit matches preview");start=finish;finish=center+new Vector2(145,50);Send("down",start);Send("move",finish);Check(r.IsSphereArrangementPaused,"second drag pauses");var before=sphere.transform.position;Send("cancel",finish);Check(!r.IsSphereArrangementPaused&&sphere.transform.position==before,"actual cancel does not commit");bool left=(bool)rt.GetProperty("IsLeftHanded",F).GetValue(r);start=center+new Vector2(left?80:-80,-80);finish=start+new Vector2(left?25:-25,-30);Send("down",start);Send("move",finish);Check(r.IsSphereArrangementPaused,"actual drag-to-place pauses");Send("cancel",finish);Check(!r.IsSphereArrangementPaused&&((List<SphereAttackAgent>)Get("_spheres")).Count==1,"cancel placement creates nothing");Finish("PASS");}catch(Exception e){Finish("FAIL "+e.GetBaseException().Message);}};EditorApplication.update+=tick;return new{status="RUNNING"};}
